'use client';
import { useEffect,useState } from 'react';
import Link from 'next/link';
export default function Vendor(){const [record,setRecord]=useState<{title:string;reason:string;status:string}|null>(null),[error,setError]=useState(''),[message,setMessage]=useState(''),[sent,setSent]=useState(false),[busy,setBusy]=useState(false);
 useEffect(()=>{const token=window.location.hash.slice(1);fetch('/api/vendor',{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error.message);setRecord(data);}).catch(e=>setError(e.message));},[]);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/vendor/correction',{method:'POST',headers:{Authorization:`Bearer ${window.location.hash.slice(1)}`,'Content-Type':'application/json'},body:JSON.stringify({correction:message})});const data=await r.json();if(!r.ok)throw new Error(data.error.message);setSent(true);}catch(e){setError(e instanceof Error?e.message:'Could not submit.');}finally{setBusy(false);}}
 return <main id="main" className="account-page"><Link href="/" className="wordmark">Countersign ↗</Link><section className="account-card"><p className="eyebrow">PRIVATE VENDOR PORTAL</p><h1>{record?.title??'Your payment case'}</h1>{error&&<p role="alert" className="form-error">{error}</p>}{record&&<><p>{record.reason}</p><p>Status: <strong>{record.status.replaceAll('_',' ')}</strong></p>{sent?<p role="status">Correction received. Your customer will review it before changing any approved terms.</p>:<form onSubmit={submit}><label htmlFor="correction">Add a correction or evidence reference</label><textarea id="correction" required maxLength={8000} value={message} onChange={e=>setMessage(e.target.value)}/><button className="button primary" disabled={busy}>{busy?'Submitting…':'Submit correction'}</button></form>}<p className="small-muted">This link only exposes your assigned case. Submitting a correction does not approve payment or change your verified destination. Do not include passwords or wallet secrets.</p></>}</section></main>;
}
